pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // configure a benign log and initialize the contract
        GoodLog log = new GoodLog();
        c.SetLogFile(address(log));
        c.Initialized();

        // adversarial party: a log implementation that reverts
        RevertingLog badLog = new RevertingLog();

        // attacker tries to redirect the log after initialization; on P this
        // has no effect, on M it succeeds and hijacks the log
        c.SetLogFile(address(badLog));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: after initialization, any funded actor's Put always succeeds.
        assertTrue(ok);
    }
}

contract GoodLog {
    function AddMessage(address, uint256, string memory) public pure {}
}

contract RevertingLog {
    fallback() external pure {
        revert();
    }
}

