pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogHarness log1;

    function setUp() public {
        c = new C();
        log1 = new LogHarness();
        c.SetLogFile(address(log1));
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, address newLog) public {
        vm.assume(newLog != address(0));
        vm.assume(newLog != address(log1));
        amount = bound(amount, 1, 1 ether);
        address actor = address(0xA11CE);
        vm.deal(actor, amount);

        // Attempting to redirect the log after initialization must not be
        // possible; whatever happens, the message of a subsequent Put must
        // be recorded in the originally configured Log.
        try c.SetLogFile(newLog) { /* mutant may succeed here */ } catch { /* reference reverts */ }

        vm.prank(actor);
        c.Put{value: amount}(0);

        (,,, uint lastVal) = log1.History(0);
        assertTrue(lastVal == amount);
    }
}

contract LogHarness {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

