pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address logAddr) public {
        vm.assume(logAddr != address(0));
        vm.assume(logAddr != address(c));
        // Configuration phase: initialize MinSum and seal the contract.
        c.SetMinSum(bound(seed, 0, type(uint128).max));
        c.Initialized();

        // Rule: after initialization, SetLogFile must always revert.
        bool ok;
        vm.prank(address(uint160(bound(seed + 1, 1, type(uint160).max))));
        try c.SetLogFile(logAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "SetLogFile must revert after initialization");
    }
}

