pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 lockTime, address newLog) public {
        // keep params in the admissible domain
        vm.assume(newLog != address(0));
        vm.assume(newLog != address(c));
        lockTime = bound(lockTime, 0, type(uint256).max - block.timestamp);

        // configure the log while not yet initialized (works on both versions)
        c.SetLogFile(newLog);

        // initialize: from now on SetMinSum/SetLogFile must be locked
        c.Initialized();

        // advance time and exercise a normal Put (admissible, no overflow thanks to bound)
        vm.deal(address(this), 1 ether);
        c.Put{value: 0}(lockTime);

        // RULE: after initialization, SetLogFile must revert on every admissible input
        bool ok;
        try c.SetLogFile(newLog) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

