pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.SetLogFile(address(new Logger()));
        c.Initialized();
        vm.warp(1000);
    }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(actor != address(0));
        amount1 = bound(amount1, 1, 1e30);
        amount2 = bound(amount2, 1, amount1 - 1 < 1 ? 1 : amount1 - 1);
        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.Put{value: amount1}(0);
        uint256 before = c.Acc(actor).balance;

        vm.prank(actor);
        c.Put{value: amount2}(0);

        assertTrue(c.Acc(actor).balance >= before);
    }
}

